DO $$ DECLARE definition text; name text; signature regprocedure; BEGIN FOREACH name IN ARRAY ARRAY['commit_project_setup_excel_upload','commit_project_setup_upload_validated','commit_project_setup_excel_upload_v2'] LOOP signature:=CASE WHEN name='commit_project_setup_excel_upload_v2' THEN 'public.commit_project_setup_excel_upload_v2(uuid,jsonb,jsonb,jsonb,jsonb)'::regprocedure ELSE ('public.'||name||'(uuid,jsonb,jsonb,jsonb)')::regprocedure END; SELECT pg_get_functiondef(signature) INTO definition; definition:=replace(definition,E'BEGIN\n',E'BEGIN\n  IF jsonb_typeof(coalesce(p_boq_rows, ''[]''::jsonb)) <> ''array'' OR jsonb_array_length(coalesce(p_boq_rows, ''[]''::jsonb)) > 0 THEN\n    RAISE EXCEPTION ''BOQ sheet uploading is off. Enter this project BOQ in the BOQ tab; Material Plan and Subcontract Rates remain available.'' USING ERRCODE=''42501'';\n  END IF;\n'); IF name='commit_project_setup_excel_upload' THEN definition:=replace(definition,'WHERE h.id=v_boq_id','WHERE h.id=v_boq_id AND h.entry_mode=''legacy'''); END IF; EXECUTE definition; END LOOP; END $$;